#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/heap_kasan.h>
#include <zephyr/sys/kasan.h>
#include <string.h>
#include <stdlib.h>

#if CONFIG_SYS_HEAP_KASAN_MALLOC

K_HEAP_DEFINE(kasan_test_heap, 1024);

static void asan_sys_heap_test_normal(void)
{
    void *ptr = k_heap_alloc(&kasan_test_heap, 16, K_NO_WAIT);
    zassert_not_null(ptr, "Allocation failed");
    memset(ptr, 0xAA, 16);
    k_heap_free(&kasan_test_heap, ptr);
}

static void asan_sys_heap_test_overflow(void)
{
    void *ptr = k_heap_alloc(&kasan_test_heap, 16, K_NO_WAIT);
    zassert_not_null(ptr, "Allocation failed");
    /* Intentional overflow to be detected by KASAN */
    /* memset(ptr, 0xAA, 32); */
    k_heap_free(&kasan_test_heap, ptr);
}

static void asan_sys_heap_test_overflow_no_false_positive(void)
{
    void *ptr = k_heap_alloc(&kasan_test_heap, 16, K_NO_WAIT);
    zassert_not_null(ptr, "Allocation failed");
    memset(ptr, 0xAA, 16);
    k_heap_free(&kasan_test_heap, ptr);
}

static void asan_sys_heap_test_overflow_8byte(void)
{
    void *ptr = k_heap_alloc(&kasan_test_heap, 8, K_NO_WAIT);
    zassert_not_null(ptr, "Allocation failed");
    /* Intentional 8-byte overflow */
    /* memset(ptr, 0xBB, 16); */
    k_heap_free(&kasan_test_heap, ptr);
}

static void asan_sys_heap_test_zero_size_ext_ops_no_false_positive(void)
{
    void *ptr = k_heap_alloc(&kasan_test_heap, 0, K_NO_WAIT);
    zassert_is_null(ptr, "Zero-size allocation should return NULL");
}

static void asan_sys_heap_suite_setup(void)
{
    /* k_heap_init(&kasan_test_heap, ...); K_HEAP_DEFINE already initializes it. */
}

static void asan_sys_heap_suite_teardown(void)
{
    /* Clean up if necessary */
}

static void asan_sys_heap_before_test(void *fixture)
{
    ARG_UNUSED(fixture);
}

static void asan_sys_heap_after_test(void *fixture)
{
    ARG_UNUSED(fixture);
}

ZTEST_SUITE(asan_sys_heap_test_suite, asan_sys_heap_suite_setup, asan_sys_heap_suite_teardown,
            asan_sys_heap_before_test, asan_sys_heap_after_test, NULL);

ZTEST(asan_sys_heap_test_suite, normal)
{
    asan_sys_heap_test_normal();
}

ZTEST(asan_sys_heap_test_suite, overflow)
{
    asan_sys_heap_test_overflow();
}

ZTEST(asan_sys_heap_test_suite, overflow_no_false_positive)
{
    asan_sys_heap_test_overflow_no_false_positive();
}

ZTEST(asan_sys_heap_test_suite, overflow_8byte)
{
    asan_sys_heap_test_overflow_8byte();
}

ZTEST(asan_sys_heap_test_suite, zero_size_ext_ops_no_false_positive)
{
    asan_sys_heap_test_zero_size_ext_ops_no_false_positive();
}

#else /* CONFIG_SYS_HEAP_KASAN_MALLOC */

/* If KASAN for sys_heap is not enabled, this file should not define any tests. */
/* This prevents compilation errors when the KASAN feature is not available. */

#endif /* CONFIG_SYS_HEAP_KASAN_MALLOC */
